{"hypotheses": [
  {
    "name": "Hypothesis1",
    "mechanism": "Firms with strong momentum during market upturns but lower liquidity tend to have a higher return as liquidity dries up during market downturns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "Illiquidity", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis2",
    "mechanism": "Firms with a high book to market ratio and high momentum in a positive term spread environment would yield higher returns due to value and momentum premiums.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "BM"},
        {"weight": 0.5, "primitive": "Mom12m"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis3",
    "mechanism": "Firms with high asset growth and low illiquidity perform better during periods of a negative term spread as they are perceived as safer investments.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "AssetGrowth"},
        {"weight": -0.5, "primitive": "Illiquidity"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 30
  },
  {
    "name": "Hypothesis4",
    "mechanism": "Firms showing strong past return performance and being more tangible are likely to deliver stronger performance in a down market as they are perceived as safer investments.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": 0.5, "primitive": "tang"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "tang", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Hypothesis5",
    "mechanism": "Firms with higher R&D expenses and higher momentum are likely to outperform in a up market due to growth and momentum premiums.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "RD"},
        {"weight": 0.5, "primitive": "Mom12m"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Hypothesis6",
    "mechanism": "Firms with lower liquidity and higher analyst optimism perform better in a down market as they are underfollowed and likely to be undervalued.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "Illiquidity"},
        {"weight": 1.0, "primitive": "AOP"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Hypothesis7",
    "mechanism": "Firms with a high book to market ratio and high asset growth in a positive term spread environment would yield higher returns due to value and growth premiums.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "BM"},
        {"weight": 0.5, "primitive": "AssetGrowth"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Hypothesis8",
    "mechanism": "Firms with a lower bid-ask spread and high asset growth perform better in a up market as they are more liquid and likely to attract more investors.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "BidAskSpread"},
        {"weight": 1.0, "primitive": "AssetGrowth"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
